  .bh-main {
  flex: 1;
  position: relative;

  &__page {
    transition: margin-left 0.4s ease;
    margin-left: 0;

    &--full-width {
      margin-left: calc(var(--sidbar-width) - 250px);
    }
  }
}

@media (min-width: 540px) {
  .bh-main {
    &__page {
      margin-left: var(--sidbar-width);

